function konsertina(){$(".elementMainTitle").addClass("expand");$('<span class="expand"></span>').prependTo(".elementMainTitle",".konsertina .title");$("li.disabled",".konsertina").each(function(index,element){$(".explanation",".konsertina .disabled").slideUp();$(".elementMainTitle > span",element).remove()});$('li[class="title"] .explanation',".konsertina").hide();if($("li.startOpen .explanation",".konsertina").length>0)$(".elementMainTitle","li.startOpen").removeClass("expand").addClass("collapse").children(".expand").removeClass("expand").addClass("collapse");
$(".elementMainTitle").click(function(){if($(this).parent().children(".explanation").length>0&&$(this).parent().hasClass("title"))if($(this).is(".expand")){$(this).parent().find(".explanation").slideDown();$(this).removeClass("expand").addClass("collapse").children(".expand").removeClass("expand").addClass("collapse")}else{$(this).parent().find(".explanation").slideUp();$(this).removeClass("collapse").addClass("expand").children(".collapse").removeClass("collapse").addClass("expand")}})}
function konsertinaActivatingElement(step){konsertinaClosingAllElement(step);konsertinaEnablingElement(step);konsertinaExpandingElement(step)}function konsertinaClosingAllElement(step){$(".explanation",".title").slideUp();$(".collapse").addClass("expand").removeClass("collapse")}
function konsertinaEnablingElement(step){$(".disabled#step_"+step).children(".elementMainTitle").prepend('<span class="collapse"></span>');$("#step_"+step).removeClass("disabled").addClass("title").children(".elementMainTitle").addClass("collapse").removeClass("expand")}function konsertinaExpandingElement(step){$("#step_"+step).find(".explanation").slideDown()};